import styled from "styled-components";
import Modal from "react-bootstrap/Modal";

export const StyledPublishModal = styled(Modal)`
  .modal-header {
    border-bottom: none;
    padding-bottom: 0;
  }

  .modal-body {
    padding: 30px;
  }
`
